from solution import add_elements
import pytest
from hypothesis import given
import hypothesis.strategies as st


def ref(arr, k):
    # Obviously-correct model: number of digits ignores sign,
    # i.e. len(str(abs(x))) <= 2  <=>  -99 <= x <= 99
    return sum(x for x in arr[:k] if -99 <= x <= 99)


def test_example_from_spec():
    assert add_elements([111, 21, 3, 4000, 5, 6, 7, 8, 9], 4) == 24


def test_negative_two_digit_example():
    # -21 has two digits, -3 has one digit; both must be counted
    assert add_elements([-21, -3, -111, 5], 2) == -24


def test_negative_two_digit_boundary():
    assert add_elements([-10, -99, -100, -9], 4) == -10 + -99 + -9


def test_negative_single_digit_included():
    assert add_elements([-5], 1) == -5


def test_positive_boundaries_99_100():
    # 99 is 2 digits (included), 100 is 3 digits (excluded)
    assert add_elements([99, 100], 2) == 99
    assert add_elements([100], 1) == 0


def test_negative_boundaries_99_100():
    # -99 is 2 digits (included), -100 is 3 digits (excluded)
    assert add_elements([-99, -100], 2) == -99
    assert add_elements([-100], 1) == 0


def test_zero_has_one_digit():
    assert add_elements([0], 1) == 0
    assert add_elements([0, 100, 0], 3) == 0


def test_only_first_k_considered():
    assert add_elements([1, 2, 3, 4, 5], 2) == 3
    assert add_elements([111, 21, 3, 4000, 5, 6, 7, 8, 9], 2) == 21
    assert add_elements([5, 6, 150], 3) == 11
    assert add_elements([5, 6, 150], 2) == 11


def test_k_equals_len():
    assert add_elements([111, 21, 3, 4000], 4) == 24
    assert add_elements([-11, -22, 5], 3) == -28


def test_all_excluded_gives_zero():
    assert add_elements([100, 101, 1000, -100, -1000, 4000], 6) == 0


@given(st.data())
def test_property_matches_reference_model(data):
    arr = data.draw(
        st.lists(st.integers(min_value=-1000, max_value=1000), min_size=1, max_size=30)
    )
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    assert add_elements(arr, k) == ref(arr, k)


@given(st.data())
def test_property_negative_two_digit_range_fully_included(data):
    # Every element in [-99, -10] has exactly two digits, so sum == sum of slice
    arr = data.draw(
        st.lists(st.integers(min_value=-99, max_value=-10), min_size=1, max_size=30)
    )
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    assert add_elements(arr, k) == sum(arr[:k])


@given(st.data())
def test_property_first_k_truncation(data):
    arr = data.draw(
        st.lists(st.integers(min_value=-1000, max_value=1000), min_size=1, max_size=30)
    )
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    # Elements at positions >= k must not affect the result
    suffix = data.draw(
        st.lists(st.integers(min_value=-1000, max_value=1000), max_size=10)
    )
    extended = arr[:k] + suffix
    # result on extended with same k equals result on original prefix
    assert add_elements(extended, k) == add_elements(arr[:k], k)
    assert add_elements(arr, k) == add_elements(arr[:k], k)


@given(st.data())
def test_property_monotonic_k_with_nonnegative(data):
    arr = data.draw(
        st.lists(st.integers(min_value=0, max_value=99), min_size=1, max_size=20)
    )
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    # all non-negative <= 99 are all included, so extending k can only increase sum
    if k < len(arr):
        assert add_elements(arr, k + 1) == add_elements(arr, k) + arr[k]
    assert add_elements(arr, len(arr)) == sum(arr)
